import loggingimport randomimport asyncioimport feedparserfrom telegram import Update, ChatPermissionsfrom telegram.ext import (    ApplicationBuilder,    CommandHandler,    MessageHandler,    filters,    ContextTypes,)from dotenv import load_dotenvimport os# Load secretsload_dotenv()BOT_TOKEN = os.getenv("BOT_TOKEN")BOT_NAME = os.getenv("BOT_NAME", "Luchy")OWNER_ID = int(os.getenv("OWNER_ID", "0"))# Setup logginglogging.basicConfig(    format="%(asctime)s - %(name)s - %(levelname)s - %(message)s", level=logging.INFO)logger = logging.getLogger(BOT_NAME)# Load pickup lineswith open("pickups.txt", "r", encoding="utf-8") as f:    PICKUPS = [line.strip() for line in f if line.strip()]# ----------------------- BOT COMMANDS -----------------------async def start(update: Update, context: ContextTypes.DEFAULT_TYPE):    await update.message.reply_text(f"🔥 Welcome to {BOT_NAME}! Type /help to explore me.")async def help_command(update: Update, context: ContextTypes.DEFAULT_TYPE):    await update.message.reply_text(        "✨ Available Commands:\n"        "/hi - Get a pickup line 😉\n"        "/game1 - Trivia game 🎮\n"        "/game2 - Guess number 🎲\n"        "/advice - Random life advice 💡\n"        "/news - Get fresh diplomatic news 🌍\n"        "/ban /unban /warn /mute /unmute /pin /unpin etc. for admins"    )# ----------------------- FUN FEATURES -----------------------async def pickup(update: Update, context: ContextTypes.DEFAULT_TYPE):    if update.message.text.lower() == "hi":        line = random.choice(PICKUPS)        await update.message.reply_text(line)async def advice(update: Update, context: ContextTypes.DEFAULT_TYPE):    advices = [        "Don’t compare yourself with others, compare yourself with yesterday’s you.",        "Discipline beats motivation, always.",        "Be so focused on improving yourself that you have no time to hate others.",    ]    await update.message.reply_text(random.choice(advices))# ----------------------- GAMES -----------------------GAME1_QUESTIONS = {    "Who is known as the Father of Computers?": "Charles Babbage",    "What is the capital of Japan?": "Tokyo",    "Who wrote Romeo and Juliet?": "William Shakespeare",}GAME2_SECRET = Noneasync def game1(update: Update, context: ContextTypes.DEFAULT_TYPE):    question, answer = random.choice(list(GAME1_QUESTIONS.items()))    context.user_data["answer"] = answer    await update.message.reply_text(f"Trivia Time 🤓:\n{question}")async def game1_answer(update: Update, context: ContextTypes.DEFAULT_TYPE):    if "answer" in context.user_data:        correct = context.user_data["answer"]        if update.message.text.strip().lower() == correct.lower():            await update.message.reply_text("✅ Correct! You are smart 🔥")            del context.user_data["answer"]async def game2(update: Update, context: ContextTypes.DEFAULT_TYPE):    global GAME2_SECRET    GAME2_SECRET = random.randint(1, 20)    await update.message.reply_text("🎲 Guess the number between 1-20!")async def game2_guess(update: Update, context: ContextTypes.DEFAULT_TYPE):    global GAME2_SECRET    if GAME2_SECRET:        try:            guess = int(update.message.text.strip())            if guess == GAME2_SECRET:                await update.message.reply_text("🔥 Correct! You guessed it.")                GAME2_SECRET = None        except:            pass# ----------------------- NEWS -----------------------async def news(update: Update, context: ContextTypes.DEFAULT_TYPE):    feed = feedparser.parse("https://www.aljazeera.com/xml/rss/all.xml")    headlines = [entry.title for entry in feed.entries[:5]]    await update.message.reply_text("🌍 Top Diplomatic News:\n" + "\n".join(headlines))# ----------------------- GROUP MANAGEMENT -----------------------async def ban(update: Update, context: ContextTypes.DEFAULT_TYPE):    if update.message.reply_to_message:        await update.effective_chat.ban_member(update.message.reply_to_message.from_user.id)        await update.message.reply_text("🚫 User banned.")async def unban(update: Update, context: ContextTypes.DEFAULT_TYPE):    if context.args:        user_id = int(context.args[0])        await update.effective_chat.unban_member(user_id)        await update.message.reply_text("✅ User unbanned.")async def warn(update: Update, context: ContextTypes.DEFAULT_TYPE):    if update.message.reply_to_message:        await update.message.reply_text("⚠️ Warning issued!")async def mute(update: Update, context: ContextTypes.DEFAULT_TYPE):    if update.message.reply_to_message:        await update.effective_chat.restrict_member(            update.message.reply_to_message.from_user.id,            ChatPermissions(can_send_messages=False),        )        await update.message.reply_text("🔇 User muted.")async def unmute(update: Update, context: ContextTypes.DEFAULT_TYPE):    if update.message.reply_to_message:        await update.effective_chat.restrict_member(            update.message.reply_to_message.from_user.id,            ChatPermissions(can_send_messages=True),        )        await update.message.reply_text("🔊 User unmuted.")# ----------------------- MAIN -----------------------def main():    app = ApplicationBuilder().token(BOT_TOKEN).build()    # Commands    app.add_handler(CommandHandler("start", start))    app.add_handler(CommandHandler("help", help_command))    app.add_handler(CommandHandler("advice", advice))    app.add_handler(CommandHandler("game1", game1))    app.add_handler(CommandHandler("game2", game2))    app.add_handler(CommandHandler("news", news))    app.add_handler(CommandHandler("ban", ban))    app.add_handler(CommandHandler("unban", unban))    app.add_handler(CommandHandler("warn", warn))    app.add_handler(CommandHandler("mute", mute))    app.add_handler(CommandHandler("unmute", unmute))    # Games logic    app.add_handler(MessageHandler(filters.TEXT & ~filters.COMMAND, game1_answer))    app.add_handler(MessageHandler(filters.TEXT & ~filters.COMMAND, game2_guess))    # Pickup lines    app.add_handler(MessageHandler(filters.TEXT & ~filters.COMMAND, pickup))    logger.info(f"Starting {BOT_NAME}...")    app.run_polling()if __name__ == "__main__":    main()